<div class="page-head"><div><div class="eyebrow">Sales pipeline</div><h1>Enquiries & CRM</h1><div class="muted">Track new travel requests, team ownership and the next customer action.</div></div><?php if (Auth::can('enquiries.manage')): ?><a class="btn" href="<?= nh_e(APP_BASE_PATH) ?>/admin/enquiries/create">＋ Create enquiry</a><?php endif ?></div>
<section class="card"><form class="toolbar" method="get" action="<?= nh_e(APP_BASE_PATH) ?>/admin/enquiries"><input type="search" name="q" value="<?= nh_e($search) ?>" placeholder="Search reference, customer or contact"><select name="status"><option value="">All statuses</option><?php foreach (Enquiry::STATUSES as $s): ?><option value="<?= nh_e($s) ?>" <?= $status === $s ? 'selected' : '' ?>><?= nh_e(ucwords(str_replace('_',' ',$s))) ?></option><?php endforeach ?></select><button class="btn" type="submit">Filter</button><?php if ($search !== '' || $status !== ''): ?><a class="btn secondary" href="<?= nh_e(APP_BASE_PATH) ?>/admin/enquiries">Clear</a><?php endif ?></form><p class="muted"><?= (int) $data['total'] ?> enquiry record(s)</p><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Travel dates</th><th>Travellers</th><th>Priority</th><th>Status</th><th>Assigned to</th><th></th></tr></thead><tbody><?php foreach ($data['items'] as $e): ?><tr><td><strong><?= nh_e($e['enquiry_number']) ?></strong><br><span class="muted"><?= nh_e(date('d M Y', strtotime($e['created_at']))) ?></span></td><td><?= nh_e($e['customer_name'] ?: 'Unlinked customer') ?><br><span class="muted"><?= nh_e($e['customer_phone'] ?: $e['customer_email'] ?: '') ?></span></td><td><?= $e['travel_start_date'] ? nh_e(date('d M Y', strtotime($e['travel_start_date']))) : '—' ?><?php if ($e['travel_end_date']): ?><br><span class="muted">to <?= nh_e(date('d M Y', strtotime($e['travel_end_date']))) ?></span><?php endif ?></td><td><?= nh_e($e['traveller_count'] ?: '—') ?></td><td><span class="pill <?= nh_e($e['priority']) ?>"><?= nh_e($e['priority']) ?></span></td><td><span class="pill <?= nh_e($e['status']) ?>"><?= nh_e(str_replace('_',' ',$e['status'])) ?></span></td><td><?= nh_e($e['assignee_name'] ?: 'Unassigned') ?></td><td><a href="<?= nh_e(APP_BASE_PATH) ?>/admin/enquiries/view?id=<?= (int) $e['id'] ?>">Open →</a></td></tr><?php endforeach ?><?php if (!$data['items']): ?><tr><td colspan="8" class="muted">No enquiries found. Adjust the filters or create a new enquiry.</td></tr><?php endif ?></tbody></table></div><?php if ($data['pages'] > 1): ?><div class="pagination"><?php for ($p=1; $p <= $data['pages']; $p++): ?><?php if ($p === $data['page']): ?><span><strong><?= $p ?></strong></span><?php else: ?><a href="?q=<?= rawurlencode($search) ?>&status=<?= rawurlencode($status) ?>&page=<?= $p ?>"><?= $p ?></a><?php endif ?><?php endfor ?></div><?php endif ?></section>
